import { tags } from "typia";

/**
 * Line-level checkout preview item representing a single cart line and its
 * computed monetary breakdown.
 *
 * This object aggregates information from the underlying cart item, associated
 * product and SKU, and pricing configuration. It exposes base price, applied
 * discounts, tax amounts, and allocated shipping or surcharge components for
 * one logical item line in the cart.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCartCheckoutPreviewItem = {
  /**
   * Identifier of the cart item that this preview line corresponds to.
   *
   * This typically matches the primary key of a record in
   * shopping_mall_cart_items and is used by clients to correlate preview
   * lines with existing cart UI elements.
   */
  cart_item_id: string & tags.Format<"uuid">;

  /**
   * Display name of the product associated with this cart item.
   *
   * The value is resolved from the product catalog and may incorporate
   * localization or variant-specific naming rules.
   */
  product_name: string;

  /**
   * Identifier of the concrete SKU selected for this cart item.
   *
   * This value maps to a record in shopping_mall_skus and is used for
   * inventory checks, price determination, and variant resolution.
   */
  sku_id: string & tags.Format<"uuid">;

  /**
   * Quantity of the SKU included in this cart line for the purpose of this
   * checkout preview.
   *
   * The value reflects any adjustments made during validation or eligibility
   * computation and is used to scale monetary amounts in this preview line.
   */
  quantity: number & tags.Type<"int32">;

  /**
   * Base unit price of the SKU for this cart item prior to discounts, taxes,
   * and surcharges.
   *
   * This value is derived from the product catalog and current pricing rules
   * in effect at the time of preview generation.
   */
  unit_price: number;

  /**
   * Total discount amount applied to this line item as part of the checkout
   * preview.
   *
   * This may include contributions from coupons, promotions, or other
   * business rules that reduce the effective line price.
   */
  discount_amount: number;

  /**
   * Total tax amount calculated for this line item in the preview.
   *
   * The computation uses tax rules associated with the region, product
   * category, and other configuration tables relevant to tax policy.
   */
  tax_amount: number;

  /**
   * Portion of the total shipping fee that is allocated to this line item for
   * presentation purposes.
   *
   * This value is useful for displaying per-item shipping costs but does not
   * represent a separate charge; the final payable shipping total is provided
   * at the order summary level.
   */
  shipping_fee_share?: number | undefined;

  /**
   * Portion of any payment method surcharges or similar fees that is
   * allocated to this line item in the preview.
   *
   * This allocation is primarily for display and analysis and may not
   * directly correspond to how charges are recorded in financial ledgers.
   */
  surcharge_share?: number | undefined;

  /**
   * Final total amount for this line item after applying discounts, taxes,
   * shipping allocation, and surcharge allocation.
   *
   * This value represents the effective cost attributable to this cart line
   * within the overall checkout preview.
   */
  line_total: number;
};
